package com.jinloes.practice;
public class Solution { public static boolean nextPermutation(int[] values){ int pivot=values.length-2; while(pivot>=0 && values[pivot]>=values[pivot+1]) pivot--; if(pivot<0){ reverse(values,0,values.length-1); return false; } int successor=values.length-1; while(values[successor]<=values[pivot]) successor--; swap(values,pivot,successor); reverse(values,pivot+1,values.length-1); return true; } private static void reverse(int[] v,int l,int r){ while(l<r) swap(v,l++,r--); } private static void swap(int[] v,int i,int j){ int t=v[i]; v[i]=v[j]; v[j]=t; } }
